class Solution:
    def getPermutation(self, n: int, k: int) -> str:
        nums = [str(i) for i in range(1, n + 1)]
        k -= 1
        res = ""
        import math
        for i in range(n - 1, -1, -1):
            idx, k = divmod(k, math.factorial(i))
            res += nums.pop(idx)
        return res

