#include <iostream>
#include <vector>
#include <string>
#include <numeric>

using namespace std;

string getPermutation(int n, int k) {
    vector<int> nums(n);
    iota(nums.begin(), nums.end(), 1);
    vector<int> factorial(n, 1);
    for (int i = 1; i < n; i++) factorial[i] = factorial[i - 1] * i;

    k--;
    string res = "";
    for (int i = n - 1; i >= 0; i--) {
        int idx = k / factorial[i];
        k %= factorial[i];
        res += to_string(nums[idx]);
        nums.erase(nums.begin() + idx);
    }
    return res;
}

int main() {
    int n, k;
    if (!(cin >> n >> k)) return 0;
    cout << "\"" << getPermutation(n, k) << "\"" << endl;
    return 0;
}

