const fs = require('fs');

function getPermutation(n, k) {
    const nums = [];
    const factorial = [1];
    for (let i = 1; i < n; i++) {
        factorial[i] = factorial[i - 1] * i;
        nums.push(i);
    }
    nums.push(n);

    k--;
    let res = "";
    for (let i = n - 1; i >= 0; i--) {
        const idx = Math.floor(k / factorial[i]);
        k %= factorial[i];
        res += nums[idx];
        nums.splice(idx, 1);
    }
    return res;
}

